// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "hardhat/console.sol";

/**
 * @title ProofPassPassport
 * @dev Manages professional identity and ProofScore.
 */
contract ProofPassPassport {
    struct Passport {
        string passportId; // e.g., PP-2026-001
        uint256 proofScore;
        bool isVerified;
        string metadataURI; // IPFS hash for profile data
    }

    mapping(address => Passport) public passports;
    uint256 public nextIdNum = 1;

    event PassportCreated(address indexed user, string passportId);
    event ProofScoreUpdated(address indexed user, uint256 newScore);

    /**
     * @dev Creates a new passport with a unique ID format: PP-2026-XXX
     */
    function createPassport(string memory _metadataURI) external {
        require(!passports[msg.sender].isVerified, "Passport exists");

        string memory passportId = string(abi.encodePacked("PP-2026-", _uint2str(nextIdNum)));
        nextIdNum++;

        passports[msg.sender] = Passport({
            passportId: passportId,
            proofScore: 50, // Base score
            isVerified: true,
            metadataURI: _metadataURI
        });

        emit PassportCreated(msg.sender, passportId);
    }

    /**
     * @dev Updates the user's ProofScore. For a hackathon MVP, anyone can call this, 
     * but in production it should be restricted to the Reputation Contract.
     */
    function updateScore(address _user, uint256 _score) external {
        require(passports[_user].isVerified, "Passport does not exist");
        passports[_user].proofScore = _score;
        emit ProofScoreUpdated(_user, _score);
    }

    /**
     * @dev Helper to convert uint to string
     */
    function _uint2str(uint256 _i) internal pure returns (string memory _uintAsString) {
        if (_i == 0) {
            return "0";
        }
        uint256 j = _i;
        uint256 len;
        while (j != 0) {
            len++;
            j /= 10;
        }
        bytes memory bstr = new bytes(len);
        uint256 k = len;
        while (_i != 0) {
            k = k - 1;
            uint8 temp = (48 + uint8(_i - (_i / 10) * 10));
            bytes1 b1 = bytes1(temp);
            bstr[k] = b1;
            _i /= 10;
        }
        return string(bstr);
    }
}

contracts/RecruiterEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title RecruiterEscrow
 * @dev Recruiter stakes funds. Released to professional upon response.
 */
contract RecruiterEscrow {
    struct Escrow {
        address recruiter;
        address professional;
        uint256 amount;
        bool isResolved;
    }

    mapping(uint256 => Escrow) public escrows;
    uint256 public nextEscrowId;

    event EscrowCreated(uint256 indexed escrowId, address recruiter, address professional, uint256 amount);
    event EscrowReleased(uint256 indexed escrowId, address professional);

    /**
     * @dev Recruiter creates an escrow by sending native ETH (or mocked USDC for hackathon).
     */
    function createEscrow(address _professional) external payable {
        require(msg.value > 0, "Stake required");
        uint256 escrowId = nextEscrowId++;

        escrows[escrowId] = Escrow({
            recruiter: msg.sender,
            professional: _professional,
            amount: msg.value,
            isResolved: false
        });

        emit EscrowCreated(escrowId, msg.sender, _professional, msg.value);
    }

    /**
     * @dev Professional claims the escrow.
     */
    function releaseEscrow(uint256 _escrowId) external {
        Escrow storage esc = escrows[_escrowId];
        require(!esc.isResolved, "Already resolved");
        // For hackathon: Professional claims it directly
        require(msg.sender == esc.professional, "Only professional can claim");

        esc.isResolved = true;
        (bool success, ) = esc.professional.call{value: esc.amount}("");
        require(success, "Transfer failed");

        emit EscrowReleased(_escrowId, esc.professional);
    }
}

